package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/**
 * Lines for the player's mentor, The Chairman (content/data/mentor.json, generated by tools/content/gen_mentor.py).
 * Triggers: `chapter:N`, `done:N`, `mission:<id>`, `open:<business>`, `event:<name>`, `tip:N`.
 */
@Serializable
data class MentorContent(val name: String, val lines: List<MentorLineDef>) {
    @kotlinx.serialization.Transient val byTrigger: Map<String, List<MentorLineDef>> = lines.groupBy { it.trigger }

    companion object {
        val EMPTY = MentorContent("", emptyList())
        /** Moments the app reacts to (keys after "event:"). */
        val EVENTS = setOf(
            "tier", "manager", "expansion", "hq", "conglomerate", "holding", "trade", "short", "property_bought", "property_sold",
            "renovation", "tower", "disaster", "foreclosure", "luxury", "auction_won", "auction_lost", "world_event", "business_sold",
            "payment_missed", "loan_taken", "loan_repaid", "tax_filed", "tax_audited", "restructured", "phoenix", "crown_passed",
            "nemesis", "quarter", "ipo",
        )
    }
}

@Serializable
data class MentorLineDef(val id: String, val trigger: String, val text: String)
